import {RoadRouter,lengthOf,samplePath} from './roads.js';
import {hash} from './lowpoly.js';
const UTILS=['electric','water','gas'];
export class DemoOperations{
 constructor(town){this.town=town;this.router=new RoadRouter(town.roads);this.jobs=[];this.incidents=[];this.commands=[];this.sequence=0;this.time=8*3600;const station=town.networks.electric.nodes.find(n=>n.id===town.networks.electric.stationId);this.depot=this.router.index.nearest(station);this.graph={};for(const u of UTILS){const net=town.networks[u],adj=new Map(),nodes=new Map(net.nodes.map(n=>[n.id,n]));for(const e of net.edges){if(!adj.has(e.from))adj.set(e.from,[]);adj.get(e.from).push(e);}const ordered=[],queue=[net.sourceId];for(let i=0;i<queue.length;i++)for(const e of adj.get(queue[i])||[]){ordered.push(e);queue.push(e.to);}this.graph[u]={adj,nodes,ordered};}}
 record(type,payload){this.commands.push({id:'CMD-'+(++this.sequence),at:this.time,type,payload});}
 breakAsset(target){const existing=this.incidents.find(i=>i.assetId===target.id&&this.active(i));if(existing)return existing;if(this.incidents.filter(i=>this.active(i)).length>=128)throw Error('The demo supports 128 simultaneous incidents. Complete repairs or reset demo actions.');const utility=target.utility||'electric',net=this.town.networks[utility],edge=net.edges.find(e=>e.id===target.edgeId);if(!edge)throw Error('No connected utility edge for this asset.');const i={id:'INC-'+(this.incidents.length+1),assetId:target.id,kind:target.kind==='pole'?'broken_pole':utility==='water'?'water_main_break':utility==='electric'?'line_fault':'gas_leak',utility,edgeId:edge.id,x:target.x,z:target.z,createdAt:this.time,jobId:null};this.incidents.push(i);this.record('break_asset',{...i});return i;}
 active(i,time=this.time){if(time<i.createdAt)return false;const job=this.jobs.find(j=>j.id===i.jobId);return !job||time<job.arrivalAt+job.workSeconds;}
 dispatch(target,incident=null){const existing=this.jobs.find(j=>j.targetId===target.id&&!['completed','future'].includes(this.jobState(j).status));if(existing)return existing;if(this.jobs.filter(j=>!['completed','future'].includes(this.jobState(j).status)).length>=8)throw Error('All eight demo crews are busy. Let a visit finish first.');const route=this.router.route(this.depot,target.front||target),id='JOB-'+(this.jobs.length+1),driveSeconds=Math.max(6,route.length/9),workSeconds=incident?360+hash(id+this.town.seed)%180:150;const job={id,targetId:target.id,premiseId:incident?null:target.id,incidentId:incident?.id||null,utility:incident?.utility||'electric',kind:incident?'repair':'field_visit',label:incident?incident.kind.replaceAll('_',' '):target.address,route:route.points,routeLength:route.length,startAt:this.time,arrivalAt:this.time+driveSeconds,workSeconds,endAt:this.time+2*driveSeconds+workSeconds,visitPoint:{x:target.x,z:target.z},roadPoint:{x:route.end.x,z:route.end.z}};this.jobs.push(job);if(incident)incident.jobId=id;this.record('dispatch',{jobId:id,targetId:target.id,incidentId:incident?.id||null});return job;}
 jobState(job,time=this.time){const elapsed=time-job.startAt,drive=job.arrivalAt-job.startAt;if(elapsed<0)return {status:'future',position:null};if(time>=job.endAt)return {status:'completed',position:this.depot};if(elapsed<drive)return {status:'en_route',position:samplePath(job.route,Math.min(job.routeLength,elapsed*job.routeLength/drive))};if(elapsed<drive+job.workSeconds){const work=elapsed-drive,walk=Math.min(1,work/35,(job.workSeconds-work)/35),a=job.roadPoint,b=job.visitPoint;return {status:'on_site',position:samplePath(job.route,job.routeLength),agent:{x:a.x+(b.x-a.x)*walk,z:a.z+(b.z-a.z)*walk}};}const progress=(elapsed-drive-job.workSeconds)/drive,p=samplePath(job.route,job.routeLength*(1-progress));return {status:'returning',position:{...p,dx:-p.dx,dz:-p.dz}};}
 impact(time=this.time){const unavailable=Object.fromEntries(UTILS.map(u=>[u,new Set()])),disabled=Object.fromEntries(UTILS.map(u=>[u,new Set()])),allEdges=Object.fromEntries(UTILS.map(u=>[u,new Set()]));for(const i of this.incidents){if(!this.active(i,time))continue;const graph=this.graph[i.utility],edge=this.town.networks[i.utility].edges.find(e=>e.id===i.edgeId);disabled[i.utility].add(edge.id);allEdges[i.utility].add(edge.id);const queue=[edge.to];for(let n=0;n<queue.length;n++){const node=graph.nodes.get(queue[n]);if(node.premiseId)unavailable[i.utility].add(node.premiseId);for(const e of graph.adj.get(node.id)||[]){allEdges[i.utility].add(e.id);queue.push(e.to);}}}return {unavailable,disabled,allEdges};}
 applyFlow(flow,scenario){if(!this.incidents.some(i=>this.active(i))){flow.electric.allOff=scenario==='outage';flow.electric.unavailable=new Set();flow.electric.unpoweredEdges=new Set();if(scenario==='outage')flow.electric.edgeEnabled=new Map(this.town.networks.electric.edges.filter(e=>e.kind==='supply').map(e=>[e.id,false]));flow.powerRevision='normal:'+scenario;return flow;}const impact=this.impact();for(const u of UTILS){for(const id of impact.unavailable[u]){const value=flow.homes.get(id);value[u]=0;if(u==='electric')Object.assign(value,{loadKW:0,generationKW:0,importKW:0,exportKW:0});}const graph=this.graph[u],totals=new Map([...graph.nodes].map(([id,n])=>[id,n.premiseId?flow.homes.get(n.premiseId)[u]:0]));for(const i of this.incidents)if(i.utility==='water'&&this.active(i)){const edge=this.town.networks.water.edges.find(e=>e.id===i.edgeId);totals.set(edge.from,(totals.get(edge.from)||0)+.65);}const edgeFlows=new Map(),edgeEnabled=new Map();for(const e of [...graph.ordered].reverse()){const enabled=!impact.disabled[u].has(e.id),v=enabled?(totals.get(e.to)||0):0;edgeFlows.set(e.id,v);edgeEnabled.set(e.id,enabled);totals.set(e.from,(totals.get(e.from)||0)+v);}flow[u]={...flow[u],source:totals.get(this.town.networks[u].sourceId)||0,edgeFlows,edgeEnabled,unavailable:impact.unavailable[u],unpoweredEdges:impact.allEdges[u]};}flow.electric.allOff=scenario==='outage';if(scenario==='outage')for(const e of this.town.networks.electric.edges)if(e.kind==='supply')flow.electric.edgeEnabled.set(e.id,false);flow.powerRevision=this.incidents.filter(i=>this.active(i)).map(i=>i.id).join(',')+':'+scenario;return flow;}
 export(){return {schemaVersion:'viewer-demo-operations/1.0',townId:this.town.id,seed:this.town.seed,timeSeconds:this.time,commands:this.commands,incidents:this.incidents,jobs:this.jobs,notice:'Browser demo only. Not engine work orders or billing events.'};}
}
